            "kind": "operation",
            "scale": "operation",
            "detail": "adaptive_layer_norm",
            "code": "a_norm = sigmoid(Linear(LayerNorm(conditioning_signal))) * LayerNorm(single_state) + LinearNoBias(LayerNorm(conditioning_signal))",
            "operation": "adaptive_layer_norm"
